/*
 * prog30_escape_unescape – reproduced from the analysed binary
 *
 * Behaviour:
 *   prog30_escape_unescape escape   <string>   – prints the string with
 *       backslash, double‑quote, newline and tab characters escaped.
 *
 *   prog30_escape_unescape unescape <string>   – performs the inverse
 *       conversion (\\ → \\, \" → ", \n → newline, \t → tab).  Any other
 *       sequence “\\X” is treated as the literal character X.
 *
 *   If the number of arguments is wrong, the mode is unknown or the
 *   input string is longer than 1023 characters the program prints a
 *   short diagnostic and exits.
 *
 *   All output is produced with `puts`, i.e. a trailing newline is added.
 */

#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_INPUT 1023   /* same limit used by the original binary */

/* ------------------------------------------------------------------ */
/* Escape a plain string – backslash, double‑quote, newline and tab are
   turned into the corresponding C‑style escape sequences.               */
static void do_escape(const char *in)
{
    size_t len = strlen(in);
    /* In the worst case every character becomes two characters. */
    char *out = malloc(len * 2 + 1);
    if (!out) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    size_t j = 0;
    for (size_t i = 0; i < len; ++i) {
        unsigned char c = (unsigned char)in[i];
        switch (c) {
            case '\\': out[j++] = '\\'; out[j++] = '\\'; break;
            case '"':  out[j++] = '\\'; out[j++] = '"'; break;
            case '\n': out[j++] = '\\'; out[j++] = 'n';  break;
            case '\t': out[j++] = '\\'; out[j++] = 't';  break;
            default:    out[j++] = c;                     break;
        }
    }
    out[j] = '\0';
    puts(out);
    free(out);
}

/* ------------------------------------------------------------------ */
/* Un‑escape a string that was produced by the above routine.  The
   recognised escape sequences are the same as in `do_escape`.  Any
   other “\\X” sequence is interpreted as the literal character X.      */
static void do_unescape(const char *in)
{
    size_t len = strlen(in);
    char *out = malloc(len + 1);          /* result can never be longer */
    if (!out) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    size_t i = 0, j = 0;
    while (i < len) {
        if (in[i] == '\\' && i + 1 < len) {
            char nxt = in[i + 1];
            switch (nxt) {
                case '\\': out[j++] = '\\'; i += 2; break;
                case '"':  out[j++] = '"';  i += 2; break;
                case 'n':   out[j++] = '\n'; i += 2; break;
                case 't':   out[j++] = '\t'; i += 2; break;
                default:    out[j++] = nxt;  i += 2; break; /* unknown */
            }
        } else {
            out[j++] = in[i++];
        }
    }
    out[j] = '\0';
    puts(out);
    free(out);
}

/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    const char *mode = argv[1];
    const char *input = argv[2];

    if (strlen(input) > MAX_INPUT) {
        puts("INVALID");
        return 0;
    }

    if (strcmp(mode, "escape") == 0) {
        do_escape(input);
    } else if (strcmp(mode, "unescape") == 0) {
        do_unescape(input);
    } else {
        puts("INVALID_MODE");
    }
    return 0;
}
